package com.example.melonstools.data;

import com.example.melonstools.department.DepartmentPolicy;
import com.google.gson.*;import net.minecraft.nbt.*;import net.minecraft.server.level.*;import net.minecraft.world.level.saveddata.SavedData;import java.util.*;

/** Phase 4-C: audited department tasks, isolated from DailyTaskManager/HqTaskSavedData. */
public class DepartmentTaskSavedData extends SavedData{
 public static final String DATA_NAME="melon_department_tasks"; public static final String OPEN="open",CLAIMED="claimed",IN_PROGRESS="in_progress",SUBMITTED="submitted",COMPLETED="completed",FAILED="failed",CANCELLED="cancelled"; private final List<Task> tasks=new ArrayList<>(); private int sequence;
 public static DepartmentTaskSavedData get(ServerLevel l){return l.getDataStorage().computeIfAbsent(DepartmentTaskSavedData::load,DepartmentTaskSavedData::new,DATA_NAME);} public static DepartmentTaskSavedData load(CompoundTag tag){DepartmentTaskSavedData d=new DepartmentTaskSavedData();d.sequence=tag.getInt("Sequence");ListTag a=tag.getList("Tasks",Tag.TAG_COMPOUND);for(int i=0;i<a.size();i++)d.tasks.add(Task.load(a.getCompound(i)));return d;} @Override public CompoundTag save(CompoundTag tag){tag.putInt("Sequence",sequence);ListTag a=new ListTag();for(Task t:tasks)a.add(t.save());tag.put("Tasks",a);return tag;} public List<Task> tasks(){return Collections.unmodifiableList(tasks);} private Task byId(String id){for(Task t:tasks)if(t.id.equals(id))return t;return null;} private static String s(String v){return v==null?"":v.trim();} private static void audit(ServerPlayer p,String action,String id,boolean ok,String why,String after){OperationAuditSavedData.get(p.serverLevel()).record(p,action,id,ok?"ok":"denied",why,"",after);} private static boolean uuidListHas(String csv,String uuid){return Arrays.asList(csv.split(",")).contains(uuid);} private static String addUuid(String csv,String uuid){if(uuid==null||uuid.isBlank()||uuidListHas(csv,uuid))return csv;return csv==null||csv.isBlank()?uuid:csv+","+uuid;}
 public Task create(ServerPlayer actor, JsonObject o){DepartmentPolicy.Identity id=DepartmentPolicy.identity(actor);boolean op=actor.hasPermissions(2);String target=DepartmentPolicy.normalizeDepartment(o.has("targetDepartment")?o.get("targetDepartment").getAsString():id.department());if(!DepartmentPolicy.canPublishDepartmentTask(id.department(),id.position(),id.level(),target,op)){audit(actor,"dept_task_create","",false,"permission","");return null;}Task t=new Task();t.id="dept-task-"+(++sequence);t.status=OPEN;t.issuingDepartment=id.department();t.targetDepartment=target;t.targetPosition=s(o.has("targetPosition")?o.get("targetPosition").getAsString():"");t.minLevel=o.has("minLevel")?Math.max(0,o.get("minLevel").getAsInt()):0;t.title=s(o.has("title")?o.get("title").getAsString():"");t.description=s(o.has("description")?o.get("description").getAsString():"");t.priority=s(o.has("priority")?o.get("priority").getAsString():"normal");t.goal=o.has("goal")?Math.max(1,o.get("goal").getAsInt()):1;t.rewardSummary=s(o.has("rewardSummary")?o.get("rewardSummary").getAsString():"");t.createdByUuid=actor.getUUID().toString();t.createdByName=actor.getScoreboardName();t.createdAt=t.updatedAt=System.currentTimeMillis();tasks.add(t);setDirty();audit(actor,"dept_task_create",t.id,true,"target="+target,t.status);return t;}
 public boolean claim(ServerPlayer p,String id){Task t=byId(id);DepartmentPolicy.Identity u=DepartmentPolicy.identity(p);boolean ok=t!=null&&OPEN.equals(t.status)&&matches(u,t);if(ok){t.status=CLAIMED;t.claimedByUuid=p.getUUID().toString();t.participantUuids=addUuid(t.participantUuids,t.claimedByUuid);touch(t);setDirty();}audit(p,"dept_task_claim",id,ok,"target_identity",ok?t.status:"");return ok;} public boolean start(ServerPlayer p,String id){Task t=byId(id);String u=p.getUUID().toString();boolean ok=t!=null&&(CLAIMED.equals(t.status)||OPEN.equals(t.status))&&(u.equals(t.claimedByUuid)||matches(DepartmentPolicy.identity(p),t));if(ok){t.status=IN_PROGRESS;t.claimedByUuid=u;t.participantUuids=addUuid(t.participantUuids,u);touch(t);setDirty();}audit(p,"dept_task_start",id,ok,"participant",ok?t.status:"");return ok;} public boolean submit(ServerPlayer p,String id,int progress,String note){Task t=byId(id);String u=p.getUUID().toString();boolean ok=t!=null&&(IN_PROGRESS.equals(t.status)||CLAIMED.equals(t.status))&&(u.equals(t.claimedByUuid)||uuidListHas(t.participantUuids,u));if(ok){t.progress=Math.min(t.goal,Math.max(t.progress,progress));t.note=s(note);t.status=SUBMITTED;touch(t);setDirty();}audit(p,"dept_task_submit",id,ok,"progress="+progress,ok?t.status:"");return ok;} public boolean close(ServerPlayer p,String id,String status,String reason){Task t=byId(id);DepartmentPolicy.Identity u=DepartmentPolicy.identity(p);boolean st=COMPLETED.equals(status)||FAILED.equals(status)||CANCELLED.equals(status);boolean perm=t!=null&&(p.hasPermissions(2)||DepartmentPolicy.isFacilityDirector(u.department(),u.position(),u.level())||DepartmentPolicy.canPublishDepartmentTask(u.department(),u.position(),u.level(),t.targetDepartment,false));boolean ok=st&&perm&&t!=null&&!COMPLETED.equals(t.status);if(ok){t.status=status;t.note=s(reason);touch(t);setDirty();}audit(p,"dept_task_close",id,ok,"status="+status,ok?t.status:"");return ok;} private static boolean matches(DepartmentPolicy.Identity u,Task t){return (t.targetDepartment.isBlank()||u.department().equals(t.targetDepartment))&&(t.targetPosition.isBlank()||u.position().equals(t.targetPosition))&&u.level()>=t.minLevel;} private static void touch(Task t){t.updatedAt=System.currentTimeMillis();}
 public JsonObject toJsonFor(ServerPlayer viewer){DepartmentPolicy.Identity u=DepartmentPolicy.identity(viewer);boolean terminal=DepartmentPolicy.isFacilityDirector(u.department(),u.position(),u.level())||viewer.hasPermissions(2);JsonObject r=new JsonObject();JsonArray a=new JsonArray();for(Task t:tasks)if(terminal||matches(u,t)||viewer.getUUID().toString().equals(t.claimedByUuid)||uuidListHas(t.participantUuids,viewer.getUUID().toString()))a.add(t.toJson());r.add("items",a);r.addProperty("skeleton",false);return r;}
 public static class Task{public String id="",status=OPEN,issuingDepartment="",targetDepartment="",targetPosition="",title="",description="",priority="normal",createdByUuid="",createdByName="",claimedByUuid="",participantUuids="",rewardSummary="",note="";public int minLevel,progress,goal=1;public long createdAt,updatedAt,dueAt;CompoundTag save(){CompoundTag t=new CompoundTag();t.putString("Id",id);t.putString("Status",status);t.putString("IssuingDepartment",issuingDepartment);t.putString("TargetDepartment",targetDepartment);t.putString("TargetPosition",targetPosition);t.putInt("MinLevel",minLevel);t.putString("Title",title);t.putString("Description",description);t.putString("Priority",priority);t.putString("CreatedByUuid",createdByUuid);t.putString("CreatedByName",createdByName);t.putString("ClaimedByUuid",claimedByUuid);t.putString("ParticipantUuids",participantUuids);t.putString("Note",note);t.putInt("Progress",progress);t.putInt("Goal",goal);t.putString("RewardSummary",rewardSummary);t.putLong("CreatedAt",createdAt);t.putLong("UpdatedAt",updatedAt);t.putLong("DueAt",dueAt);return t;}static Task load(CompoundTag t){Task x=new Task();x.id=t.getString("Id");x.status=t.getString("Status");x.issuingDepartment=t.getString("IssuingDepartment");x.targetDepartment=t.getString("TargetDepartment");x.targetPosition=t.getString("TargetPosition");x.minLevel=t.getInt("MinLevel");x.title=t.getString("Title");x.description=t.getString("Description");x.priority=t.getString("Priority");x.createdByUuid=t.getString("CreatedByUuid");x.createdByName=t.getString("CreatedByName");x.claimedByUuid=t.getString("ClaimedByUuid");x.participantUuids=t.getString("ParticipantUuids");x.note=t.getString("Note");x.progress=t.getInt("Progress");x.goal=Math.max(1,t.getInt("Goal"));x.rewardSummary=t.getString("RewardSummary");x.createdAt=t.getLong("CreatedAt");x.updatedAt=t.getLong("UpdatedAt");x.dueAt=t.getLong("DueAt");return x;}JsonObject toJson(){JsonObject o=new JsonObject();o.addProperty("id",id);o.addProperty("status",status);o.addProperty("issuingDepartment",issuingDepartment);o.addProperty("targetDepartment",targetDepartment);o.addProperty("targetPosition",targetPosition);o.addProperty("minLevel",minLevel);o.addProperty("title",title);o.addProperty("description",description);o.addProperty("priority",priority);o.addProperty("createdByName",createdByName);o.addProperty("claimedByUuid",claimedByUuid);o.addProperty("participantUuids",participantUuids);o.addProperty("progress",progress);o.addProperty("goal",goal);o.addProperty("rewardSummary",rewardSummary);o.addProperty("note",note);o.addProperty("updatedAt",updatedAt);return o;}}
}
